-- Read-only audit for Supabase E2E. Do not run against production.
select format('%I.%I(%s)',fn_ns.nspname,fn.proname,pg_get_function_identity_arguments(fn.oid)) as function_signature, case when ref_proc.oid is not null then 'function' when ref_class.oid is not null then 'relation' when ref_type.oid is not null then 'type' else 'other' end as dependency_type, coalesce(ref_proc_ns.nspname,ref_class_ns.nspname,ref_type_ns.nspname,ref_namespace.nspname) as referenced_schema, coalesce(ref_proc.proname,ref_class.relname,ref_type.typname,ref_namespace.nspname) as referenced_object, case when ref_proc.oid is not null then 'function' when ref_class.oid is not null then 'table_or_index' when ref_type.oid is not null then 'type' when ref_namespace.oid is not null then 'schema' else 'other' end as referenced_object_type from pg_proc fn join pg_namespace fn_ns on fn_ns.oid=fn.pronamespace join pg_depend dep on dep.classid='pg_proc'::regclass and dep.objid=fn.oid left join pg_proc ref_proc on dep.refclassid='pg_proc'::regclass and dep.refobjid=ref_proc.oid left join pg_namespace ref_proc_ns on ref_proc_ns.oid=ref_proc.pronamespace left join pg_class ref_class on dep.refclassid='pg_class'::regclass and dep.refobjid=ref_class.oid left join pg_namespace ref_class_ns on ref_class_ns.oid=ref_class.relnamespace left join pg_type ref_type on dep.refclassid='pg_type'::regclass and dep.refobjid=ref_type.oid left join pg_namespace ref_type_ns on ref_type_ns.oid=ref_type.typnamespace left join pg_namespace ref_namespace on dep.refclassid='pg_namespace'::regclass and dep.refobjid=ref_namespace.oid where fn_ns.nspname='public' and coalesce(ref_proc_ns.nspname,ref_class_ns.nspname,ref_type_ns.nspname,ref_namespace.nspname) is not null order by fn.proname, referenced_schema, referenced_object;
